contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint am) public payable {
        require(address(this).balance >= 1 ether);

        // Establish a balance for this test contract in c. Deposit only if the amount is valid.
        c.Deposit{value: 1 ether}();

        // Read the caller's balance via the public getter.
        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;

        // The deciding call: attempt to CashOut `am`.
        bool reverted;
        try c.CashOut(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        if (!reverted) {
            // Success case: requires am <= balBefore, and Ether decreases by am.
            assert(am <= balBefore);
            assert(address(c).balance == contractBalBefore - am);
        } else {
            // Revert case: requires am > balBefore, and state/Ether are unchanged.
            assert(am > balBefore);
            assert(address(c).balance == contractBalBefore);
        }
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint am) public payable {
        require(address(this).balance >= 1 ether);

        // Set up a known balance for the test contract in c.
        c.Deposit{value: 1 ether}();

        // Read observable state before the deciding call.
        uint balBefore = c.balances(address(this));
        uint contractBalBefore = address(c).balance;

        // The deciding call: attempt to CashOut `am` (top-level, not nested).
        bool reverted;
        try c.CashOut(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // General rule: revert iff am > balance; success iff am <= balance and
        // the contract's Ether balance decreases by exactly am.
        assert(reverted == (am > balBefore) && (reverted || address(c).balance == contractBalBefore - am));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    function run(uint deposit, uint am) public payable {
        // Ensure we can send the deposit and that c has enough Ether to pay out if needed.
        require(deposit > 0);
        require(address(this).balance >= deposit);
        require(address(c).balance >= am);

        // Setup: deposit exactly `deposit` into c to give the caller a known balance.
        c.Deposit{value: deposit}();

        // Read observable state before the deciding call.
        uint balBefore = c.balances(address(this));
        uint cBalBefore = address(c).balance;

        // The deciding call: attempt to CashOut `am` (top-level, not nested).
        bool reverted;
        try c.CashOut(am) {
            reverted = false;
        } catch {
            reverted = true;
        }

        uint balAfter = c.balances(address(this));
        uint cBalAfter = address(c).balance;

        // General rule: revert iff am > balBefore; on success, both the caller's balance
        // and the contract's Ether balance decrease by exactly am.
        assert(reverted == (am > balBefore) && (reverted
            ? (balAfter == balBefore && cBalAfter == cBalBefore)
            : (balAfter == balBefore - am && cBalAfter == cBalBefore - am)));
    }

    receive() external payable {}
}

